require_once dirname(__DIR__,2).'/src/visibility.php';require_method('GET');$u=current_user();$id=(string)($_GET['post_id']??'');if(!can_view_post($id,$u['id']))json_response(['error'=>['code'=>'forbidden','message'=>'Post unavailable']],403);
$q=db()->prepare('SELECT c.*,(SELECT COUNT(*) FROM comment_likes l WHERE l.comment_id=c.id) AS likes,EXISTS(SELECT 1 FROM comment_likes l WHERE l.comment_id=c.id AND l.user_id=?) AS liked_by_me,u.display_name AS author_name,u.photo_media_id AS author_photo_media_id FROM comments c JOIN users u ON u.id=c.author_id WHERE c.post_id=? AND c.deleted_at IS NULL ORDER BY c.created_at,c.id LIMIT 300');$q->execute([$u['id'],$id]);json_response(['comments'=>$q->fetchAll()]);
